function validate([m, n, prices]) {
  if (!Number.isInteger(m) || m < 1 || m > 200) return 'm is between 1 and 200.';
  if (!Number.isInteger(n) || n < 1 || n > 200) return 'n is between 1 and 200.';
  if (prices.length < 1 || prices.length > 20000) return 'prices needs 1 to 20000 entries.';
  const shapes = new Set();
  for (const entry of prices) {
    if (entry.length !== 3) return 'Each price entry is [h, w, price].';
    const [h, w, price] = entry;
    if (!Number.isInteger(h) || h < 1 || h > m) return 'Each height is between 1 and m.';
    if (!Number.isInteger(w) || w < 1 || w > n) return 'Each width is between 1 and n.';
    if (!Number.isInteger(price) || price < 1 || price > 1000000) return 'Each price is between 1 and 10^6.';
    const key = h * 1000 + w;
    if (shapes.has(key)) return 'Each shape may be listed only once.';
    shapes.add(key);
  }
  return null;
}

