function sellingWood(m, n, prices) {
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (const [height, width, price] of prices) {
    dp[height][width] = price;
  }

  for (let h = 1; h <= m; h++) {
    for (let w = 1; w <= n; w++) {
      for (let cut = 1; cut <= Math.floor(h / 2); cut++) {
        dp[h][w] = Math.max(dp[h][w], dp[cut][w] + dp[h - cut][w]);
      }
      for (let cut = 1; cut <= Math.floor(w / 2); cut++) {
        dp[h][w] = Math.max(dp[h][w], dp[h][cut] + dp[h][w - cut]);
      }
    }
  }
  return dp[m][n];
}

