function sellingWood(m, n, prices) {
  const priceOf = new Map(prices.map(([h, w, p]) => [h + ',' + w, p]));
  const memo = new Map();
  const best = (h, w) => {
    const key = h + ',' + w;
    if (memo.has(key)) return memo.get(key);
    let result = priceOf.get(key) ?? 0;
    for (let top = 1; top < h; top++) result = Math.max(result, best(top, w) + best(h - top, w));
    for (let left = 1; left < w; left++) result = Math.max(result, best(h, left) + best(h, w - left));
    memo.set(key, result);
    return result;
  };
  return best(m, n);
}

