function generate(rand, size) {
  const large = size === 'large';
  const m = large ? 150 + Math.floor(rand() * 51) : 1 + Math.floor(rand() * 4);
  const n = large ? 150 + Math.floor(rand() * 51) : 1 + Math.floor(rand() * 4);
  const count = large ? 1 + Math.floor(rand() * 2000) : 1 + Math.floor(rand() * Math.min(m * n, 6));
  const top = large ? 1000000 : (rand() < 0.5 ? 10 : 1000000);
  const used = new Set();
  const prices = [];
  while (prices.length < count) {
    const smallShape = large && rand() < 0.5;
    const h = 1 + Math.floor(rand() * (smallShape ? Math.min(m, 12) : m));
    const w = 1 + Math.floor(rand() * (smallShape ? Math.min(n, 12) : n));
    const key = h * 1000 + w;
    if (used.has(key)) continue;
    used.add(key);
    prices.push([h, w, 1 + Math.floor(rand() * top)]);
  }
  return [m, n, prices];
}
